+    }
+
+    hf_id = g_new(gint, 1);
+    *hf_id = -1;
+    hf_array[pos].p_id = hf_id;
+
+    hf_array[pos].hfinfo.strings = NULL;
+    hf_array[pos].hfinfo.bitmask = 0;
